<dialog class="fullscreen-dialog ask-dialog" id="ask-dialog" aria-labelledby="ask-title"><button class="dialog-close" data-close aria-label="Close search"><?=icon('close')?></button><div class="ask-inner"><span class="eyebrow">A LITTLE CLARITY</span><h2 id="ask-title">what do you want to ask?</h2><label class="ask-input"><?=icon('search')?><input type="search" placeholder="Care, guides, collaborations…" aria-label="Search frequently asked questions" data-ask-input autocomplete="off"><kbd>↵</kbd></label><div class="ask-results" data-ask-results></div><p class="overlay-footnote">A few thoughtful answers, available right here. <kbd>esc</kbd> to close</p></div></dialog>
<dialog class="fullscreen-dialog typing-dialog" id="typing-dialog" aria-labelledby="typing-title"><button class="dialog-close" data-close aria-label="Close typing test"><?=icon('close')?></button><div class="typing-inner"><span class="eyebrow">A SMALL MOMENT OF FOCUS</span><h2 id="typing-title">words with a little care.</h2><div class="typing-stats" aria-live="off"><span><b data-wpm>0</b> wpm</span><span><b data-accuracy>100</b>% acc</span><span><b data-elapsed>0</b>s time</span></div><div class="typing-text" data-typing-text aria-hidden="true"></div><label class="typing-label" for="typing-input">Type the words above to begin. The test ends after 30 seconds.</label><textarea class="typing-input" id="typing-input" rows="2" data-typing-input aria-label="Typing test input" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Click here and start typing…"></textarea><div class="keyboard" aria-hidden="true"><?php foreach(['qwertyuiop','asdfghjkl','zxcvbnm'] as $row):?><div><?php foreach(str_split($row) as $key):?><span data-key="<?=$key?>"><?=$key?></span><?php endforeach;?></div><?php endforeach;?><div><span class="space-key" data-key=" ">space</span></div></div><div class="typing-controls"><button data-typing-reset><?=icon('replay')?>restart test</button><span><kbd>esc</kbd> close</span></div><div class="typing-result" role="status" hidden></div></div></dialog>
